"""Generate a sequence of values and count them into a histogram on the GPU."""

import sys

import numpy as np
import wgpu

MAX_COUNT = 4_000_000
MAX_SEED = 9999
MAX_BINS = 256
WORKGROUP_SIZE = 256
MAX_WORKGROUPS = 1024

SHADER = f"""
struct Params {{
    count: u32,
    seed: u32,
    bins: u32,
    stride: u32,
}};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, {MAX_BINS}>;

var<workgroup> local_hist: array<atomic<u32>, {MAX_BINS}>;

fn value_at(i: u32) -> u32 {{
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    return d % 1000u;
}}

@compute @workgroup_size({WORKGROUP_SIZE})
fn main(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_index) lid: u32,
) {{
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    var i = gid.x;
    loop {{
        if (i >= params.count) {{ break; }}
        let bin = value_at(i) * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
        i = i + params.stride;
    }}

    workgroupBarrier();
    let n = atomicLoad(&local_hist[lid]);
    if (lid < params.bins && n != 0u) {{
        atomicAdd(&hist[lid], n);
    }}
}}
"""


def read_input(path):
    with open(path) as f:
        parts = f.read().split()
    if len(parts) != 3:
        raise ValueError("input must contain exactly three numbers: <count> <seed> <bins>")
    count, seed, bins = (int(p) for p in parts)
    if not 0 <= count <= MAX_COUNT:
        raise ValueError(f"count must be between 0 and {MAX_COUNT}")
    if not 0 <= seed <= MAX_SEED:
        raise ValueError(f"seed must be between 0 and {MAX_SEED}")
    if not 1 <= bins <= MAX_BINS:
        raise ValueError(f"bins must be between 1 and {MAX_BINS}")
    return count, seed, bins


def gpu_histogram(count, seed, bins):
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    workgroups = max(1, min(MAX_WORKGROUPS, -(-count // WORKGROUP_SIZE)))
    stride = workgroups * WORKGROUP_SIZE

    params = np.array([count, seed, bins, stride], dtype=np.uint32)
    params_buf = device.create_buffer_with_data(
        data=params, usage=wgpu.BufferUsage.UNIFORM
    )
    hist_buf = device.create_buffer_with_data(
        data=np.zeros(MAX_BINS, dtype=np.uint32),
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf}},
            {"binding": 1, "resource": {"buffer": hist_buf}},
        ],
    )

    encoder = device.create_command_encoder()
    pass_ = encoder.begin_compute_pass()
    pass_.set_pipeline(pipeline)
    pass_.set_bind_group(0, bind_group)
    pass_.dispatch_workgroups(workgroups, 1, 1)
    pass_.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(hist_buf)
    return np.frombuffer(data, dtype=np.uint32)[:bins].tolist()


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    try:
        count, seed, bins = read_input(argv[1])
    except (OSError, ValueError) as e:
        print(f"error: {e}", file=sys.stderr)
        return 2

    counts = gpu_histogram(count, seed, bins)
    lines = [f"BIN {k} {n}" for k, n in enumerate(counts)]
    lines.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

